import numpy as np
from scipy.optimize import root

def eqs(x):
    a,b,beta=x
    alpha=1-beta
    return [alpha*a+beta*b-1.0,
            alpha*np.log(a)+beta*np.log(b)+10.0,
            alpha*a*np.log(a)+beta*b*np.log(b)-10.0]

# Try several starts; require 0<a<1<b, 0<beta<1
solutions=[]
for a0 in [1e-6,1e-4,1e-3,0.01,0.1,0.3]:
    for b0 in [2,10,100,1e3,1e4,1e5]:
        for beta0 in [1e-5,1e-4,1e-3,0.01,0.1,0.5]:
            r=root(eqs,[a0,b0,beta0])
            if r.success:
                a,b,beta=r.x
                if np.isfinite([a,b,beta]).all() and 0<a<1<b and 0<beta<1:
                    vals=tuple(r.x)
                    if not any(np.max(np.abs(np.array(vals)-np.array(s)))<1e-8 for s in solutions):
                        solutions.append(vals)
print('solutions',len(solutions))
for a,b,beta in solutions:
