    fwd_q=alpha*a*np.log(a)+beta*b*np.log(b)
    bwd_q=-(alpha*np.log(a)+beta*np.log(b))
    print('a,b,beta=',a,b,beta,'counts high=',beta*150000,'fwd_q=',fwd_q,'bwd_q=',bwd_q)
